sp_EditarContaReceber	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_EditarContaReceber`(\n\n    IN p_idContaReceber INT,\n\n    IN p_descricao      VARCHAR(300),\n\n    IN p_valorTotal     DECIMAL(10,2),\n\n    IN p_dthVencimento  DATE,\n\n    IN p_cliente_id     INT\n\n)\nBEGIN\n\n    UPDATE ContaReceber SET\n\n        descricao     = p_descricao,\n\n        valorTotal    = p_valorTotal,\n\n        dthVencimento = p_dthVencimento,\n\n        cliente_id    = p_cliente_id\n\n    WHERE idContaReceber = p_idContaReceber;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
